/**
 * 内置开源许可证列表与模板。
 *
 * 许可证文件中需要动态替换的占位符：
 *   {year}       -> 当前年份
 *   {author}     -> 作者名（仓库所有者）
 *   {project}    -> 项目名（仓库名）
 *   {projecturl} -> 项目网址（可选）
 */
final class LicenseService
{
    /** @var array<string, array{name: string, url: string, body: string}> */
    private static array $licenses = [];

    /**
     * 返回全部内置许可证，按常用度排序。
     *
     * @return array<string, array{name: string, url: string}>
     */
    public static function available(): array
    {
        self::init();
        $list = [];
        foreach (self::$licenses as $id => $info) {
            $list[$id] = ['name' => $info['name'], 'url' => $info['url']];
        }
        return $list;
    }

    public static function exists(string $id): bool
    {
        self::init();
        return isset(self::$licenses[$id]);
    }

    /**
     * 生成带占位符替换的 LICENSE 文本。
     *
     * @param array<string, string> $replacements
     */
    public static function render(string $id, array $replacements = []): string
    {
        self::init();
        if (!isset(self::$licenses[$id])) {
            return '';
        }
        $replacements += [
            'year' => (string) date('Y'),
            'author' => '',
            'project' => '',
            'projecturl' => '',
        ];
        $body = self::$licenses[$id]['body'];
        foreach ($replacements as $key => $value) {
            $body = str_replace('{' . $key . '}', $value, $body);
        }
        return $body;
    }

